CREATE TABLE projects (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>=1), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE documents (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>=1), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, project_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.project_id')) STORED REFERENCES projects(id));
CREATE TABLE clauses (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>=1), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE events (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>=1), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, project_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.project_id')) STORED REFERENCES projects(id));
CREATE TABLE obligations (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>=1), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, project_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.project_id')) STORED REFERENCES projects(id));
CREATE TABLE tasks (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>=1), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, project_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.project_id')) STORED REFERENCES projects(id), obligation_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.obligation_id')) STORED REFERENCES obligations(id), CHECK(json_extract(data,'$.effective_due_on') IS NULL OR (length(json_extract(data,'$.effective_due_on'))=10 AND date(json_extract(data,'$.effective_due_on'),'+0 days')=json_extract(data,'$.effective_due_on'))));
CREATE TABLE evidence (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>=1), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE extractions (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>=1), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE drafts (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>=1), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE calendars (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>=1), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE change_plans (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>=1), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE idempotency_requests (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>=1), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE reminders (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>=1), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE notifications (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>=1), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE attempts (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>=1), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE scheduler_runs (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>=1), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE digest_runs (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>=1), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE settings (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>=1), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE snapshots (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>=1), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE legacy_mappings (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>=1), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE imports (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>=1), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE audit_logs (id TEXT PRIMARY KEY, version INTEGER NOT NULL CHECK(version>=1), data TEXT NOT NULL CHECK(json_valid(data)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX tasks_occurrence ON tasks(obligation_id,json_extract(data,'$.occurrence_key'));
CREATE UNIQUE INDEX obligation_draft ON obligations(json_extract(data,'$.draft_id')) WHERE json_extract(data,'$.draft_id') IS NOT NULL;
CREATE UNIQUE INDEX reminder_key ON reminders(json_extract(data,'$.business_key'));
CREATE UNIQUE INDEX digest_key ON digest_runs(json_extract(data,'$.business_key'));
CREATE UNIQUE INDEX scheduler_key ON scheduler_runs(json_extract(data,'$.slot_key')) WHERE json_extract(data,'$.slot_key') IS NOT NULL;
CREATE UNIQUE INDEX legacy_key ON legacy_mappings(json_extract(data,'$.source_namespace'),json_extract(data,'$.entity_type'),json_extract(data,'$.legacy_id'));
CREATE INDEX tasks_project ON tasks(project_id);
CREATE INDEX documents_project ON documents(project_id);
